package br.com.brindespro.catalog;
import org.springframework.web.bind.annotation.*;import org.springframework.http.HttpStatus;import org.springframework.data.domain.*;import java.math.BigDecimal;import java.util.*;
@RestController @RequestMapping("/api") public class CatalogController {
 private final CategoryRepository categories;private final ProductRepository products;public CatalogController(CategoryRepository categories,ProductRepository products){this.categories=categories;this.products=products;}
 public record CategoryDto(Long id,String name,String slug,String imageUrl){} public record VariantDto(Long id,String color,String hex,String imageUrl,String material){} public record TierDto(Long id,int minQuantity,Integer maxQuantity,BigDecimal unitPrice){} public record ImageDto(Long id,Long variantId,String imageUrl,String altText){} public record ProductDto(Long id,String name,String slug,String description,CategoryDto category,String imageUrl,boolean active,List<VariantDto> variants,List<TierDto> tiers,List<ImageDto> images,List<String> engravingOptions,int minQuantity){}
 public static ProductDto dto(Product p){return new ProductDto(p.id,p.name,p.slug,p.description,new CategoryDto(p.category.id,p.category.name,p.category.slug,p.category.imageUrl),p.imageUrl,p.active,p.variants.stream().map(v->new VariantDto(v.id,v.color,v.hex,v.imageUrl,v.material)).toList(),p.tiers.stream().map(t->new TierDto(t.id,t.minQuantity,t.maxQuantity,t.unitPrice)).toList(),p.images.stream().map(i->new ImageDto(i.id,i.variantId,i.imageUrl,i.altText)).toList(),Arrays.stream(p.engravingOptions.split(",")).map(String::trim).toList(),p.minQuantity);}
 @GetMapping("/categories") public List<CategoryDto> categories(){return categories.findAll().stream().map(c->new CategoryDto(c.id,c.name,c.slug,c.imageUrl)).toList();}
 @GetMapping("/products") public Page<ProductDto> products(@RequestParam(defaultValue="") String q,@RequestParam(defaultValue="") String category,@RequestParam(defaultValue="") String color,@RequestParam(defaultValue="") String material,@RequestParam(defaultValue="") String engraving,@RequestParam(defaultValue="") String availability,@RequestParam(defaultValue="") String min,@RequestParam(defaultValue="") String max,@RequestParam(defaultValue="name") String sort,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="12") int size){if(page<0||size<1||size>100)throw new IllegalArgumentException("Paginação inválida.");BigDecimal minPrice=min.isBlank()?null:new BigDecimal(min);BigDecimal maxPrice=max.isBlank()?null:new BigDecimal(max);List<Product> filtered=products.findAll().stream().filter(p->p.active).filter(p->q.isBlank()||p.name.toLowerCase().contains(q.toLowerCase())).filter(p->category.isBlank()||p.category.slug.equals(category)).filter(p->color.isBlank()||p.variants.stream().anyMatch(v->v.color.equalsIgnoreCase(color))).filter(p->material.isBlank()||p.variants.stream().anyMatch(v->v.material.equalsIgnoreCase(material))).filter(p->engraving.isBlank()||Arrays.stream(p.engravingOptions.split(",")).anyMatch(e->e.trim().equalsIgnoreCase(engraving))).filter(p->availability.isBlank()||availability.equals("priced")&&lowestPrice(p).signum()>0||availability.equals("consult")&&lowestPrice(p).signum()==0).filter(p->minPrice==null||p.tiers.stream().anyMatch(t->t.unitPrice.compareTo(minPrice)>=0)).filter(p->maxPrice==null||p.tiers.stream().anyMatch(t->t.unitPrice.compareTo(maxPrice)<=0)).sorted(sort.equals("price-asc")?Comparator.comparing(this::lowestPrice):sort.equals("price-desc")?Comparator.comparing(this::lowestPrice).reversed():Comparator.comparing(p->p.name)).toList();int from=Math.min(page*size,filtered.size());return new PageImpl<>(filtered.subList(from,Math.min(from+size,filtered.size())).stream().map(CatalogController::dto).toList(),PageRequest.of(page,size),filtered.size());}
 private BigDecimal lowestPrice(Product p){return p.tiers.stream().map(t->t.unitPrice).min(Comparator.naturalOrder()).orElse(BigDecimal.ZERO);}
 @GetMapping("/products/{slug}") public ProductDto product(@PathVariable String slug){return products.findBySlugAndActiveTrue(slug).map(CatalogController::dto).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(HttpStatus.NOT_FOUND,"Produto não encontrado."));}
}
